#include <bits/stdc++.h>
using namespace std;

long long comb_table[777][777];
int n_rows, n_cols;
long long total_paths;
long long min_gap = (long long)1e18;
long long best_answer = -1;

void explore_paths(long long val1, long long val2, int idx1, int idx2) {
    long long gap = abs(val1 - val2);
    if (min_gap <= 1 || gap - comb_table[idx1][n_rows] * comb_table[idx2][n_rows] >= min_gap)
        return;

    if (idx1 == n_rows - 1 && idx2 == n_rows - 1) {
        long long current_gap = abs(val1 - val2);
        if (current_gap < min_gap) {
            min_gap = current_gap;
            best_answer = val1;
        }
        return;
    }

    if (idx1 >= n_rows) {
        long long increment1 = comb_table[idx1][n_rows] - comb_table[idx1 - 1][n_rows];
        long long sum2 = comb_table[idx2][n_rows];
        explore_paths(val1, val2 + increment1 * sum2, idx1 - 1, idx2);
    }

    if (idx2 >= n_rows) {
        long long sum1 = comb_table[idx1][n_rows];
        long long increment2 = comb_table[idx2][n_rows] - comb_table[idx2 - 1][n_rows];
        explore_paths(val1 + sum1 * increment2, val2, idx1, idx2 - 1);
    }
}

char input_line[12345];
int prefix_A[12345], prefix_B[12345];
unordered_map<long long, long long> dp_cache;

long long count_valid_paths(long long val1, long long val2, int idx1, int idx2) {
    long long state_id = val1 * 10000 + idx1 * 100 + idx2;
    if (dp_cache.count(state_id))
        return dp_cache[state_id];

    long long &optimal = dp_cache[state_id];
    long long gap = abs(val1 - val2);
    if (gap - comb_table[idx1][n_rows] * comb_table[idx2][n_rows] > min_gap) {
        return optimal = 0;
    }

    if (idx1 < n_rows || idx2 < n_rows) {
        if (idx1 >= prefix_A[idx1 + idx2] && idx2 >= prefix_B[idx1 + idx2]) {
            int total = idx1 + idx2;
            idx1 -= prefix_A[total];
            idx2 -= prefix_B[total];
            return optimal = comb_table[total][idx1];
        }
        return optimal = 0;
    }

    optimal = 0;
    char current_char = input_line[idx1 + idx2 - 1];
    if (current_char != 'B') {
        long long increment1 = comb_table[idx1][n_rows] - comb_table[idx1 - 1][n_rows];
        long long sum2 = comb_table[idx2][n_rows];
        optimal += count_valid_paths(val1, val2 + increment1 * sum2, idx1 - 1, idx2);
    }
    if (current_char != 'A') {
        long long sum1 = comb_table[idx1][n_rows];
        long long increment2 = comb_table[idx2][n_rows] - comb_table[idx2 - 1][n_rows];
        optimal += count_valid_paths(val1 + sum1 * increment2, val2, idx1, idx2 - 1);
    }
    return optimal;
}

int main() {
    scanf("%d %d", &n_rows, &n_cols);
    for (int i = 0; i <= 2 * (n_rows + n_cols); i++) {
        for (int j = 0; j <= 2 * (n_rows + n_cols); j++) {
            if (j == 0) comb_table[i][j] = 1;
            else if (i == 0) comb_table[i][j] = 0;
            else comb_table[i][j] = comb_table[i - 1][j] + comb_table[i - 1][j - 1];
        }
    }

    total_paths = comb_table[n_rows + n_cols][n_rows] * comb_table[n_rows + n_cols][n_rows];

    {
        long long a = 0, b = 0;
        int i = n_rows + n_cols, j = n_rows + n_cols;
        while (i >= n_rows && j >= n_rows) {
            if (a > b) {
                long long increment1 = comb_table[i][n_rows] - comb_table[i - 1][n_rows];
                long long sum2 = comb_table[j][n_rows];
                b += increment1 * sum2;
                i--;
            } else {
                long long sum1 = comb_table[i][n_rows];
                long long increment2 = comb_table[j][n_rows] - comb_table[j - 1][n_rows];
                a += sum1 * increment2;
                j--;
            }
        }
        min_gap = abs(a - b);
    }

    explore_paths(0, 0, n_rows + n_cols, n_rows + n_cols);
    scanf("%s", input_line);
    prefix_A[0] = prefix_B[0] = 0;
    for (int i = 0; i < 2 * (n_rows + n_cols); i++) {
        prefix_A[i + 1] = prefix_A[i] + (input_line[i] == 'A');
        prefix_B[i + 1] = prefix_B[i] + (input_line[i] == 'B');
    }

    long long final_count = count_valid_paths(0, 0, n_rows + n_cols, n_rows + n_cols);
    cout << final_count << endl;
    return 0;
}
